import csv, sys


def clean(rows):
    for r in rows:
        yield {**r, 'email': r['email'].lower()}


def main(src, dst):
    with open(src) as f, open(dst, 'w') as g:
        w = csv.DictWriter(g, fieldnames=['customer_id', 'email'])
        w.writeheader()
        for r in clean(csv.DictReader(f)):
            w.writerow(r)


if __name__ == '__main__':
    main(*sys.argv[1:])

